parameters.jsCode:
// One lead per posting, from every ATS, with the same fields. The ATS and board come
// from the Board list item that fetched them. `places`, `description` and
// `salary_mentions` are working fields for later steps (hard filters, Jev, Claude);
// Apply hard filters removes them before saving. Department and team fields are never
// read: developer relations roles often sit in Marketing.
const now = new Date().toISOString();
const leads = [];

// The postings in one Fetch board item, or null when that board's fetch failed.
function boardJobs(ats, response) {
  const body = response && !response.error ? response.body : undefined;
  if (ats === 'lever') return Array.isArray(body) ? body : null;
  return body && Array.isArray(body.jobs) ? body.jobs : null;
}

// Text helpers.
const ENTITIES = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', rsquo: '’', lsquo: '‘',
  rdquo: '”', ldquo: '“', mdash: '—', ndash: '–', hellip: '…', bull: '•', middot: '·' };
function decodeEntities(s) {
  return String(s || '').replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (m, e) => {
    if (e[0] === '#') {
      const code = e[1].toLowerCase() === 'x' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      return Number.isFinite(code) ? String.fromCodePoint(code) : m;
    }
    return ENTITIES[e.toLowerCase()] ?? m;
  });
}
function htmlText(html) {
  return decodeEntities(String(html || '')
    .replace(/<\s*(br|\/p|\/li|\/h\d|\/div)\s*\/?>/gi, '\n')
    .replace(/<[^>]+>/g, ' '));
}

// Money as short text: 161000 -> "$161K", 17.5 -> "$17.50", CAD -> "161K CAD".
function money(v, cur) {
  const n = v >= 1000 ? Math.round(v / 100) / 10 + 'K' : v.toFixed(2);
  return cur === 'USD' ? '$' + n : n;
}
function rangeText(min, max, cur) {
  const text = min === max ? money(min, cur) : money(min, cur) + ' – ' + money(max, cur);
  return cur === 'USD' ? text : text + ' ' + cur;
}

// Hourly pay counts toward the pay floor at 2,080 hours a year (40 hours x 52 weeks).
// The message keeps the hourly range and adds the yearly estimate.
const HOURS_PER_YEAR = 2080;
const yearlyEstimate = (min, max) => ', ≈ ' + rangeText(min, max, 'USD') + ' a year';

// ---------- Ashby ----------
// Pay is stated as components (Salary, EquityCashValue, Commission, Bonus...). Only
// base salary in USD, per year, month or hour, counts toward the pay floor. Anything
// else (other currencies, other intervals, no salary) is unknown pay. Live boards
// show "1 YEAR" and "1 MONTH"; "1 HOUR" follows the same pattern.
const ASHBY_PER_YEAR = { '1 YEAR': 1, '1 MONTH': 12, '1 HOUR': HOURS_PER_YEAR };
function ashbyPay(comp) {
  if (!comp) return { min: null, max: null, hourly: false };
  const components = (comp.summaryComponents || [])
    .concat((comp.compensationTiers || []).flatMap((t) => t.components || []));
  const salary = components.filter((c) =>
    c.compensationType === 'Salary' && c.currencyCode === 'USD' && ASHBY_PER_YEAR[c.interval] &&
    (typeof c.minValue === 'number' || typeof c.maxValue === 'number'));
  if (!salary.length) return { min: null, max: null, hourly: false };
  const k = (c) => ASHBY_PER_YEAR[c.interval];
  const mins = salary.map((c) => Math.round((typeof c.minValue === 'number' ? c.minValue : c.maxValue) * k(c)));
  const maxes = salary.map((c) => Math.round((typeof c.maxValue === 'number' ? c.maxValue : c.minValue) * k(c)));
  return { min: Math.min(...mins), max: Math.max(...maxes), hourly: salary.some((c) => c.interval === '1 HOUR') };
}

function ashbyPlace(text, address) {
  const a = (address && address.postalAddress) || {};
  return {
    text: String(text || '').trim(),
    country: String(a.addressCountry || '').trim(),
    region: String(a.addressRegion || '').trim(),
    locality: String(a.addressLocality || '').trim(),
  };
}

// Location from workplaceType, location and secondaryLocations (with addresses).
// isRemote is ignored: Ashby sets it on many hybrid postings.
function ashbyLead(job, board) {
  if (job.isListed === false) return null;
  const pay = ashbyPay(job.compensation);
  return {
    job_id: String(job.id),
    company: board,
    title: String(job.title || '').trim(),
    location_text: job.location || '',
    workplace_type: job.workplaceType || '',
    secondary_locations: (job.secondaryLocations || []).map((l) => l.location).filter(Boolean).join('; '),
    pay_text: ((job.compensation && job.compensation.compensationTierSummary) || '') +
      (pay.hourly ? yearlyEstimate(pay.min, pay.max) : ''),
    pay_min: pay.min,
    pay_max: pay.max,
    posting_url: job.jobUrl,
    apply_url: job.applyUrl,
    published_at: job.publishedAt || null,
    places: [ashbyPlace(job.location, job.address)]
      .concat((job.secondaryLocations || []).map((l) => ashbyPlace(l.location, l.address))),
    text: job.descriptionPlain ? String(job.descriptionPlain) : htmlText(job.descriptionHtml),
  };
}

// ---------- Greenhouse ----------
// No workplace type field: it comes from the location name ("United States - Remote",
// "San Francisco- Hybrid"). Only location.name is used as a place. The offices list is
// not: Instacart's Canada postings list "Remote - United States" as an office.
// Pay comes from pay_input_ranges (in cents, often one range per group of states).
// On-target earnings, commission and bonus ranges are skipped. The ranges have no
// interval; amounts under $1,000 are taken as hourly and counted at 2,080 hours a year.
function greenhouseWorkplace(text) {
  if (/\bhybrid\b/i.test(text)) return 'Hybrid';
  if (/\bremote\b/i.test(text)) return 'Remote';
  if (/\bon-?site\b|\bin[- ]office\b|\bin[- ]person\b/i.test(text)) return 'OnSite';
  return '';
}
const NOT_BASE = /\b(OTE|on[- ]target|commission|bonus|incentive|equity|stock)\b/i;
function greenhousePay(ranges) {
  const base = (ranges || []).filter((r) => !NOT_BASE.test(r.title || '') &&
    (typeof r.min_cents === 'number' || typeof r.max_cents === 'number'))
    .map((r) => {
      const min = (typeof r.min_cents === 'number' ? r.min_cents : r.max_cents) / 100;
      const max = (typeof r.max_cents === 'number' ? r.max_cents : r.min_cents) / 100;
      return { min, max, cur: String(r.currency_type || '').toUpperCase() };
    });
  const texts = [];
  for (const cur of [...new Set(base.map((r) => r.cur))]) {
    const group = base.filter((r) => r.cur === cur);
    const min = Math.min(...group.map((r) => r.min));
    const max = Math.max(...group.map((r) => r.max));
    const hourly = max < 1000;
    texts.push(rangeText(min, max, cur) + (hourly ? ' an hour' : '') +
      (hourly && cur === 'USD' ? yearlyEstimate(min * HOURS_PER_YEAR, max * HOURS_PER_YEAR) : '') +
      (group.length > 1 ? ' (by location)' : ''));
  }
  const yearly = base.filter((r) => r.cur === 'USD')
    .map((r) => (r.max < 1000 ? { min: Math.round(r.min * HOURS_PER_YEAR), max: Math.round(r.max * HOURS_PER_YEAR) } : r));
  return {
    text: texts.join('; '),
    min: yearly.length ? Math.min(...yearly.map((r) => r.min)) : null,
    max: yearly.length ? Math.max(...yearly.map((r) => r.max)) : null,
  };
}
function greenhouseLead(job, board) {
  const location = String((job.location && job.location.name) || '').trim();
  const pay = greenhousePay(job.pay_input_ranges);
  return {
    job_id: String(job.id),
    company: job.company_name || board,
    title: String(job.title || '').trim(),
    location_text: location,
    workplace_type: greenhouseWorkplace(location),
    secondary_locations: '',
    pay_text: pay.text,
    pay_min: pay.min,
    pay_max: pay.max,
    posting_url: job.absolute_url,
    apply_url: job.absolute_url,
    published_at: job.first_published || job.updated_at || null,
    places: [{ text: location, country: '', region: '', locality: '' }],
    // content is HTML with its own HTML escaped, so decode it once before reading it.
    text: htmlText(decodeEntities(job.content)),
  };
}

// ---------- Lever ----------
// Live workplaceType values are "onsite", "hybrid" and "remote" (the docs spell it
// "on-site"); both map to Ashby's names, which the location rules use. `country` is
// the primary location's ISO country code. Pay comes from salaryRange when it is in
// USD per year, month or hour; salaryDescription is read as description text.
const LEVER_WORKPLACE = { remote: 'Remote', hybrid: 'Hybrid', onsite: 'OnSite', 'on-site': 'OnSite' };
const LEVER_PER_YEAR = { 'per-year-salary': 1, 'per-month-salary': 12, 'per-hour-wage': HOURS_PER_YEAR };
const LEVER_INTERVAL = { 'per-year-salary': ' a year', 'per-month-salary': ' a month', 'per-week-salary': ' a week',
  'per-day-wage': ' a day', 'per-hour-wage': ' an hour', 'one-time': ' one-time' };
function leverPay(range) {
  const r = range || {};
  if (typeof r.min !== 'number' && typeof r.max !== 'number') return { text: '', min: null, max: null };
  const min = typeof r.min === 'number' ? r.min : r.max;
  const max = typeof r.max === 'number' ? r.max : r.min;
  const cur = String(r.currency || '').toUpperCase();
  const k = cur === 'USD' ? LEVER_PER_YEAR[r.interval] : undefined;
  return {
    text: rangeText(min, max, cur) + (LEVER_INTERVAL[r.interval] || '') +
      (k === HOURS_PER_YEAR ? yearlyEstimate(min * k, max * k) : ''),
    min: k ? Math.round(min * k) : null,
    max: k ? Math.round(max * k) : null,
  };
}
function leverLead(job, board) {
  const cat = job.categories || {};
  const primary = String(cat.location || '').trim();
  const all = (cat.allLocations || []).map((l) => String(l).trim()).filter(Boolean);
  const others = all.filter((l) => l !== primary);
  const pay = leverPay(job.salaryRange);
  const text = [job.descriptionPlain || htmlText(job.description)]
    .concat((job.lists || []).flatMap((l) => [l.text, htmlText(l.content)]))
    .concat([job.salaryDescriptionPlain || htmlText(job.salaryDescription), job.additionalPlain || htmlText(job.additional)])
    .filter(Boolean).join('\n');
  return {
    job_id: String(job.id),
    company: board,
    title: String(job.text || '').trim(),
    location_text: primary,
    workplace_type: LEVER_WORKPLACE[String(job.workplaceType || '').toLowerCase()] || '',
    secondary_locations: others.join('; '),
    pay_text: pay.text,
    pay_min: pay.min,
    pay_max: pay.max,
    posting_url: job.hostedUrl,
    apply_url: job.applyUrl || job.hostedUrl,
    published_at: typeof job.createdAt === 'number' ? new Date(job.createdAt).toISOString() : null,
    places: [{ text: primary, country: String(job.country || '').trim(), region: '', locality: '' }]
      .concat(others.map((l) => ({ text: l, country: '', region: '', locality: '' }))),
    text,
  };
}

const PARSE = { ashby: ashbyLead, greenhouse: greenhouseLead, lever: leverLead };

// ---------- Description for Jev and Claude ----------
// Unrelated text lowers Jev's accuracy, so the benefits and equal-opportunity text that
// usually follows the role is cut, blank lines are collapsed, and the rest is capped at
// DESCRIPTION_MAX characters.
const DESCRIPTION_MAX = 6000;
const BOILERPLATE_START = /^\W*(benefits|perks|what we offer|our benefits|equal (employment )?opportunity)\b|is an equal (employment )?opportunity employer/i;
function trimDescription(text) {
  const lines = text.split('\n').map((l) => l.replace(/\s+/g, ' ').trim());
  const kept = [];
  let length = 0;
  for (const line of lines) {
    if (length > 800 && BOILERPLATE_START.test(line)) break;
    if (!line && (!kept.length || !kept[kept.length - 1])) continue;
    kept.push(line);
    length += line.length + 1;
  }
  let out = kept.join('\n').trim();
  if (out.length > DESCRIPTION_MAX) {
    out = out.slice(0, DESCRIPTION_MAX).replace(/\s+\S*$/, '') + ' …';
  }
  return out;
}

// Dollar amounts in the full description that could be a yearly salary, such as
// "$150,000 - $190,000" or "$160K–$200K", each with the line it appears in. Jev later
// picks the base salary among them (or none), only for postings with no structured pay.
const AMOUNT = String.raw`\$\s?\d{1,3}(?:,\d{3})+(?:\.\d{1,2})?|\$\s?\d{2,3}(?:\.\d+)?\s?[kK]\b`;
const AMOUNT_TO = String.raw`\$?\s?\d{1,3}(?:,\d{3})+(?:\.\d{1,2})?|\$?\s?\d{2,3}(?:\.\d+)?\s?[kK]\b`;
const SALARY_SPAN = new RegExp(`(?:${AMOUNT})(?:\\s*USD)?(?:\\s*(?:-|–|—|to)\\s*(?:${AMOUNT_TO})(?:\\s*USD)?)?`, 'g');
function amounts(span) {
  return (span.match(/\d[\d,]*(?:\.\d+)?\s?[kK]?/g) || []).map((a) => {
    const n = parseFloat(a.replace(/,/g, ''));
    return /k$/i.test(a.trim()) ? n * 1000 : n;
  });
}
function salaryMentions(text) {
  const out = [];
  const seen = new Set();
  for (const line of text.split('\n')) {
    for (const m of line.matchAll(SALARY_SPAN)) {
      const span = m[0].trim();
      const values = amounts(span);
      const max = Math.max(...values);
      if (seen.has(span) || max < 30000 || max > 2000000) continue;
      seen.add(span);
      out.push({ span, context: line.replace(/\s+/g, ' ').trim().slice(0, 300) });
    }
  }
  return out.slice(0, 10);
}

const failed = [];
$input.all().forEach((item, i) => {
  const { ats, board } = $('Board list').itemMatching(i).json;
  const jobs = boardJobs(ats, item.json);
  if (!jobs) {
    // This board's fetch failed; the other boards still run.
    failed.push(ats + ':' + board + ' (' + String((item.json.error && item.json.error.message) || 'no posting list') + ')');
    return;
  }

  for (const job of jobs) {
    const lead = PARSE[ats](job, board);
    if (!lead) continue;
    const { places, text, ...fields } = lead;
    leads.push({
      json: {
        lead_key: ats + ':' + board + ':' + fields.job_id,
        ats,
        board,
        ...fields,
        last_seen_at: now,
        closed_at: null, // a posting seen again is open, even if it was closed earlier
        places: places.filter((p) => p.text || p.country || p.region || p.locality),
        description: trimDescription(text),
        salary_mentions: salaryMentions(text),
      },
    });
  }
});

// If no board could be fetched at all, the scan has nothing to work with: fail, so the
// crash alert says so instead of a misleading "no new leads".
if (failed.length && failed.length === $input.all().length) {
  throw new Error('No board could be fetched: ' + failed.join('; ').slice(0, 400));
}

return leads;

// One Telegram message per picked lead, in fit order. Parse mode is HTML, so escape
// posting text. The fit line is Claude's reply for the lead at the same position; if
// Claude failed, the message goes out without it. Each message also gets signed links
// for its Applied, Referral and Pass buttons, and a Search LinkedIn link.
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

// location_basis comes from Apply hard filters: us_remote, metro or unclear.
function where(lead) {
  const stated = [lead.location_text, lead.workplace_type].filter(Boolean).join(' · ');
  if (lead.location_basis === 'unclear') return 'Location unclear' + (stated ? ' (' + stated + ')' : '');
  if (lead.location_basis === 'us_remote' && !/remote/i.test(stated)) return stated + ' · Remote (US) option';
  return stated || 'Location unclear';
}

function pay(lead) {
  if (lead.pay_text) return lead.pay_text;
  if (lead.pay_extracted_text) return lead.pay_extracted_text + ' (from the description)';
  return 'Pay not listed';
}

// "Fit 84 · role 25 · stack 16 · seniority 15 · location 15 · domain 7 · fresh 6"
function breakdown(lead) {
  const p = lead.points || {};
  const parts = [['role', p.roleFamily], ['stack', p.stack], ['seniority', p.seniority],
    ['location', p.location], ['domain', p.domain], ['fresh', p.freshness]];
  if (p.referral) parts.push(['referral', p.referral]);
  return ['Fit ' + lead.fit_score].concat(parts.map(([name, v]) => name + ' ' + (v || 0))).join(' · ');
}

// Claude's reply as one clean line, or null.
function fitLine(reply) {
  const text = reply && typeof reply.merged_response === 'string' ? reply.merged_response
    : ((reply && reply.content) || []).filter((c) => c.type === 'text').map((c) => c.text).join('');
  const line = String(text || '').replace(/\s+/g, ' ').trim().replace(/^["“]|["”]$/g, '');
  return line || null;
}

// ---- Signed action links (the same block is in Build lead messages, Check Applied link,
// Check Referral link and Check Pass form). A link's signature is HMAC-SHA256 of "<action>:<lead key>"
// with the signing secret, as hex, cut to 32 characters (128 bits). HMAC-SHA256 is
// written out here because the Code node can't load Node's crypto module unless the
// instance allows it (NODE_FUNCTION_ALLOW_BUILTIN), and the Crypto node's HMAC reads
// its secret from a credential.
const K = [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];
const rotr = (x, n) => (x >>> n) | (x << (32 - n));
const utf8 = (s) => Array.from(new TextEncoder().encode(String(s)));
function sha256(input) {
  const bytes = input.slice();
  const bits = input.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  for (let i = 7; i >= 0; i--) bytes.push(i >= 4 ? 0 : (bits >>> (8 * i)) & 0xff);
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const w = new Array(64);
  for (let off = 0; off < bytes.length; off += 64) {
    for (let t = 0; t < 16; t++) {
      const j = off + 4 * t;
      w[t] = ((bytes[j] << 24) | (bytes[j + 1] << 16) | (bytes[j + 2] << 8) | bytes[j + 3]) >>> 0;
    }
    for (let t = 16; t < 64; t++) {
      const s0 = rotr(w[t - 15], 7) ^ rotr(w[t - 15], 18) ^ (w[t - 15] >>> 3);
      const s1 = rotr(w[t - 2], 17) ^ rotr(w[t - 2], 19) ^ (w[t - 2] >>> 10);
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let t = 0; t < 64; t++) {
      const t1 = (h + (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) + ((e & f) ^ (~e & g)) + K[t] + w[t]) >>> 0;
      const t2 = ((rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    [a, b, c, d, e, f, g, h].forEach((v, i) => { H[i] = (H[i] + v) >>> 0; });
  }
  return H.flatMap((x) => [x >>> 24, (x >>> 16) & 0xff, (x >>> 8) & 0xff, x & 0xff]);
}
function hmacSha256Hex(key, message) {
  let k = utf8(key);
  if (k.length > 64) k = sha256(k);
  while (k.length < 64) k.push(0);
  const inner = sha256(k.map((x) => x ^ 0x36).concat(utf8(message)));
  return sha256(k.map((x) => x ^ 0x5c).concat(inner)).map((x) => x.toString(16).padStart(2, '0')).join('');
}
const sign = (action, leadKey, secret) => hmacSha256Hex(secret, action + ':' + leadKey).slice(0, 32);
// Compares every character, so the time taken doesn't show how much of a guess was right.
function sameSignature(given, expected) {
  const a = String(given || '');
  let diff = a.length ^ expected.length;
  for (let i = 0; i < expected.length; i++) diff |= (a.charCodeAt(i) || 0) ^ expected.charCodeAt(i);
  return diff === 0;
}
// ---- end of signed action links

const secret = $('Signing secret').first().json.secret;
// This instance's public base URL. n8n builds $execution.resumeUrl from its webhook
// base URL (N8N_WEBHOOK_URL or WEBHOOK_URL) as <base>webhook-waiting/<execution id>;
// production webhooks live at <base>webhook/ (n8n's default path prefix).
const base = String($execution.resumeUrl).split('?')[0].replace(/[^/]+\/[^/]+$/, '');
const link = (action, key) => base + 'webhook/job-scout/' + action + '?lead=' + encodeURIComponent(key) +
  '&sig=' + sign(action, key, secret);
// Pass opens the Pass form, served at <base>form/ (n8n's default form prefix). The title
// and company are only shown on the form; the signature covers the lead key, and the
// page after the form shows the lead as saved.
const passLink = (lead) => base + 'form/job-scout/pass?lead=' + encodeURIComponent(lead.lead_key) +
  '&sig=' + sign('pass', lead.lead_key, secret) +
  '&title=' + encodeURIComponent(String(lead.title || '').slice(0, 120)) +
  '&company=' + encodeURIComponent(String(lead.company || '').slice(0, 80));

// ---- Search LinkedIn link: LinkedIn's own people search for the company and the role
// (unofficial URL format; no LinkedIn calls). Role terms are a short form of the title:
// drop anything in brackets, split at commas, "|", spaced hyphens and en or em dashes, and
// keep the first part without leading seniority words (Senior, Sr, Staff, Principal, Lead,
// Junior, Jr, Founding, Associate) or a trailing level (I to V, L1 to L99, a single digit).
// When that leaves one word ("Director, Customer Experience"), the next part is added.
const SENIORITY = /^(?:senior|sr\.?|staff|principal|lead|junior|jr\.?|founding|associate)\s+/i;
const LEVEL = /\s+(?:i{1,3}|iv|v|l\d{1,2}|\d)$/i;
function roleTerms(title) {
  const parts = String(title || '')
    .replace(/\([^)]*\)|\[[^\]]*\]/g, ' ')
    .split(/,|\||[–—]|\s-\s/)
    .map((part) => {
      let p = part.replace(/\s+/g, ' ').trim();
      while (SENIORITY.test(p)) p = p.replace(SENIORITY, '');
      return p.replace(LEVEL, '').trim();
    })
    .filter(Boolean);
  if (!parts.length) return '';
  return parts[0].split(' ').length === 1 && parts[1] ? parts[0] + ' ' + parts[1] : parts[0];
}
const linkedinLink = (lead) => 'https://www.linkedin.com/search/results/people/?keywords=' +
  encodeURIComponent((String(lead.company || '') + ' ' + roleTerms(lead.title)).replace(/\s+/g, ' ').trim());
// ---- end of Search LinkedIn link

const replies = $input.all();
return $('Pick leads to send').all().map(({ json: lead }, i) => {
  const line = fitLine(replies[i] && replies[i].json);
  const lines = [
    '<b>' + esc(lead.title) + '</b>',
    esc(lead.company),
    'Location: ' + esc(where(lead)),
    'Pay: ' + esc(pay(lead)),
    breakdown(lead),
  ];
  if (lead.sub_referral >= 1) lines.splice(2, 0, 'Referral available');
  if (line) lines.push('<i>' + esc(line) + '</i>');
  if (lead.published_at) lines.push('Posted: ' + String(lead.published_at).slice(0, 10));

  return {
    json: {
      row_id: lead.id,
      lead_key: lead.lead_key,
      fit_score: lead.fit_score,
      fit_line: line,
      text: lines.join('\n'),
      silent: true,
      button_text: 'Open posting',
      button_url: lead.posting_url,
      linkedin_url: linkedinLink(lead),
      applied_url: link('applied', lead.lead_key),
      referral_url: link('referral', lead.lead_key),
      pass_url: passLink(lead),
    },
  };
});

// The first message of the daily ping. With leads to send, it says how many and makes a
// sound. With none, it is the whole ping: one silent "no new leads" message with
// today's counts. Both say how many leads Jev couldn't score; those are judged again on
// the next scan.
//   scanned:  postings fetched from the boards in this scan
//   filtered: of those, the ones that failed a hard rule, including a salary Jev found
//             in the description below the pay floor
//   unscored: leads whose Jev request still failed after the retries
const leadCount = $('Build lead messages').isExecuted ? $('Build lead messages').all().length : 0;

const results = new Map($('Apply hard filters').all().map((i) => [i.json.lead_key, i.json.filter_result]));
for (const { json } of $('Score and select').all()) {
  if (json.lead_key && results.has(json.lead_key)) results.set(json.lead_key, json.filter_result);
}
const scanned = results.size;
const filtered = [...results.values()].filter((r) => r !== 'passed').length;
const unscored = $('Read Jev answers').isExecuted
  ? $('Read Jev answers').all().filter((i) => i.json.scoring_state === 'unscored').length
  : 0;

const retrying = unscored + " couldn't be scored (retrying next scan)";
let text;
if (leadCount > 0) {
  text = 'Job Scout: ' + leadCount + ' new ' + (leadCount === 1 ? 'lead' : 'leads') + ' today';
  if (unscored) text += ' · ' + retrying;
} else {
  text = 'Job Scout: no new leads today\n' +
    scanned + ' ' + (scanned === 1 ? 'posting' : 'postings') + ' scanned · ' + filtered + ' filtered out · ' +
    (unscored ? retrying : "0 couldn't be scored");
}
return [{ json: { text, silent: leadCount === 0, lead_count: leadCount, scanned, filtered, unscored } }];

// The header node outputs Telegram's reply, so pick the lead messages back up. On an
// empty day there are none, and the ping ends with the header.
if (!$('Build lead messages').isExecuted) return [];
return $('Build lead messages').all().map((item) => ({ json: item.json }));

// Hard rules from Job Scout config: location, pay floor, excluded titles.
// Every posting is checked on every scan, so a config change also applies to
// leads saved earlier. The first rule a lead breaks goes in filter_result
// ("location", "pay_floor" or "excluded_title"); a lead that breaks none gets
// "passed". Unknown pay or location never breaks a rule.
// The department and team fields are never used: DevRel roles often sit in Marketing.
const cfg = $('Job Scout config').first().json;
const rules = cfg.locationRules || {};
const payFloor = Number(cfg.payFloor) || 0;

// Case-insensitive match on whole words, so "Finance" doesn't match "Fintech".
function wordsRx(list) {
  const terms = (list || []).map((t) => String(t).trim()).filter(Boolean);
  if (!terms.length) return null;
  const alt = terms
    .map((t) => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/\s+/g, '\\s+'))
    .join('|');
  return new RegExp('(?<![\\p{L}\\p{N}])(?:' + alt + ')(?![\\p{L}\\p{N}])', 'iu');
}
const has = (rx, s) => Boolean(rx && s && rx.test(s));

const US_STATES = new Set(('AL AK AZ AR CA CO CT DE DC FL GA HI ID IL IN IA KS KY LA ME MD MA MI MN MS ' +
  'MO MT NE NV NH NJ NM NY NC ND OH OK OR PA RI SC SD TN TX UT VT VA WA WV WI WY').split(' '));
// Only used when a location has no country (Ashby address, Lever country code).
// Lever and Greenhouse often name a city alone ("Stockholm"), so common non-US cities
// and countries are listed too.
const NON_US_TEXT = wordsRx(['Canada', 'UK', 'United Kingdom', 'England', 'Scotland', 'Europe', 'EMEA', 'EU',
  'European Union', 'APAC', 'LATAM', 'Latin America', 'Asia', 'India', 'Australia', 'New Zealand', 'Mexico',
  'Brazil', 'Argentina', 'Colombia', 'Chile', 'Germany', 'France', 'Spain', 'Italy', 'Ireland', 'Netherlands',
  'Belgium', 'Switzerland', 'Austria', 'Sweden', 'Norway', 'Denmark', 'Finland', 'Poland', 'Portugal',
  'Lithuania', 'Estonia', 'Czechia', 'Romania', 'Greece', 'Turkey', 'Japan', 'Korea', 'South Korea', 'China',
  'Hong Kong', 'Taiwan', 'Singapore', 'Vietnam', 'Indonesia', 'Philippines', 'Malaysia', 'Thailand', 'Israel',
  'UAE', 'United Arab Emirates', 'Saudi Arabia', 'Qatar', 'South Africa', 'Nigeria', 'Kenya', 'Egypt',
  'London', 'Manchester', 'Edinburgh', 'Dublin', 'Paris', 'Berlin', 'Munich', 'Hamburg', 'Amsterdam',
  'Brussels', 'Zurich', 'Geneva', 'Vienna', 'Stockholm', 'Oslo', 'Copenhagen', 'Helsinki', 'Warsaw', 'Krakow',
  'Prague', 'Lisbon', 'Madrid', 'Barcelona', 'Milan', 'Rome', 'Vilnius', 'Tallinn', 'Bucharest', 'Athens',
  'Istanbul', 'Tel Aviv', 'Dubai', 'Abu Dhabi', 'Riyadh', 'Doha', 'Tokyo', 'Seoul', 'Beijing', 'Shanghai',
  'Shenzhen', 'Taipei', 'Jakarta', 'Manila', 'Ho Chi Minh', 'Hanoi', 'Bangkok', 'Kuala Lumpur', 'Bangalore',
  'Bengaluru', 'Mumbai', 'Delhi', 'Hyderabad', 'Pune', 'Chennai', 'Sydney', 'Melbourne', 'Auckland',
  'Toronto', 'Vancouver', 'Montreal', 'Ottawa', 'Calgary', 'Mexico City', 'Sao Paulo', 'São Paulo',
  'Buenos Aires', 'Bogota', 'Bogotá', 'Santiago', 'Lagos', 'Nairobi', 'Cape Town', 'Johannesburg']);
const REMOTE = wordsRx(['remote']);
const usNames = rules.usCountryNames || ['United States', 'USA', 'US'];
const US_TEXT = wordsRx(usNames);
const usKey = (s) => String(s).toLowerCase().replace(/\./g, '').replace(/\s+/g, ' ').trim();
const US_KEYS = new Set(usNames.map(usKey));
const metros = (rules.metros || []).map((m) => ({
  cities: wordsRx(m.cities),
  regions: wordsRx(m.regions),
  workplaceTypes: (m.workplaceTypes || []).map((w) => String(w).toLowerCase()),
}));

// "Plano, TX" -> "TX"
function stateCode(text) {
  const m = /,\s*([A-Z]{2})\b/.exec(text || '');
  return m && US_STATES.has(m[1]) ? m[1] : '';
}

function countryOf(p) {
  if (p.country) return US_KEYS.has(usKey(p.country)) ? 'us' : 'other';
  if (has(US_TEXT, p.text) || stateCode(p.text)) return 'us';
  if (has(NON_US_TEXT, p.text)) return 'other';
  return 'unknown';
}

// One location of a posting: "us_remote", "metro", "unclear" or "no".
function placeVerdict(p, workplaceType) {
  const country = countryOf(p);
  if (country === 'other') return 'no';
  const remote = workplaceType === 'remote' || has(REMOTE, p.text);
  if (remote) {
    if (rules.usRemote === false) return 'no';
    return country === 'us' ? 'us_remote' : 'unclear';
  }
  const region = p.region || stateCode(p.text);
  for (const m of metros) {
    const typeOk = !workplaceType || m.workplaceTypes.includes(workplaceType);
    const inCity = has(m.cities, p.locality) || has(m.cities, p.text);
    const regionOk = !region || has(m.regions, region);
    if (inCity && regionOk) return typeOk ? 'metro' : 'no';
  }
  // A location with no city might still be in a metro, but only when it names the US
  // ("United States") or the metro's region ("Texas"). A lone city name that isn't in a
  // metro ("Houston", "San Francisco- Hybrid") fails.
  const cityKnown = Boolean(p.locality) || /,/.test(p.text);
  const maybeMetro = metros.some((m) =>
    (!workplaceType || m.workplaceTypes.includes(workplaceType)) &&
    (region ? has(m.regions, region) : has(m.regions, p.text) || country === 'us'));
  return !cityKnown && maybeMetro ? 'unclear' : 'no';
}

function locationBasis(places, workplaceType) {
  if (!places.length) return 'unclear';
  const verdicts = places.map((p) => placeVerdict(p, workplaceType));
  for (const v of ['us_remote', 'metro', 'unclear']) if (verdicts.includes(v)) return v;
  return '';
}

const EXCLUDED = wordsRx(cfg.excludedTitles);
// A title with one of these words is never excluded: "Software Engineer, Finance Platform".
const OVERRIDES = wordsRx(cfg.excludedTitleOverrides);

return $input.all().map(({ json }) => {
  // Working fields from Normalize postings aren't saved; scoring reads them from that node.
  const { places, description, salary_mentions, ...lead } = json;
  const basis = locationBasis(places || [], String(lead.workplace_type || '').toLowerCase());
  let result = 'passed';
  if (!basis) result = 'location';
  else if (typeof lead.pay_max === 'number' && lead.pay_max < payFloor) result = 'pay_floor';
  else if (has(EXCLUDED, lead.title) && !has(OVERRIDES, lead.title)) result = 'excluded_title';
  return { json: { ...lead, location_basis: basis, filter_result: result } };
});

// One Jev request per lead that needs judging, with all questions in one request.
// A lead is judged only while it can still be sent (New, unsent, passed the filters,
// not closed, first seen within the freshness window) and only when its scoring input changed:
// the fingerprint hashes the whole request (profile summary, role families, model,
// questions and posting text). Weights, seniority targets and the minimum are applied
// later in code, so changing them needs no new Jev calls.
const cfg = $('Job Scout config').first().json;
const DAY = 24 * 60 * 60 * 1000;
const windowDays = Number(cfg.freshnessWindowDays) || 30;
const NONE = 'None of these';

// Today's postings, with the description and salary mentions that aren't saved.
const postings = new Map($('Normalize postings').all().map((i) => [i.json.lead_key, i.json]));

// Days since Job Scout first saw the lead. A lead can be sent (and so is worth
// judging) for freshnessWindowDays after that, however old the posting is.
function daysSinceFirstSeen(lead) {
  const t = lead.first_seen_at ? new Date(lead.first_seen_at).getTime() : NaN;
  return isNaN(t) ? 0 : (Date.now() - t) / DAY;
}

// 112-bit string hash (two cyrb53 seeds), so code can tell when the input changed.
function cyrb53(str, seed) {
  let h1 = 0xdeadbeef ^ seed, h2 = 0x41c6ce57 ^ seed;
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16).padStart(14, '0');
}
const fingerprintOf = (s) => cyrb53(s, 1) + cyrb53(s, 2);

// Role families come from the config. "None of these" lets Jev say a job fits none.
const families = {};
for (const f of cfg.roleFamilies || []) {
  families[f.name] = { what: f.description || '', example_titles: f.titleKeywords || [] };
}
families[NONE] = {
  what: 'Any other kind of job, such as backend-only, infrastructure, data or security engineering; ' +
    'sales, account management or customer success management; partner, alliances or systems-integrator roles; recruiting; finance; accounting, tax or business-process consulting; operations; ' +
    'design; or marketing that is not developer relations',
};

const QUESTIONS = {
  role_family: {
    type: 'choice',
    instructions: {
      question: 'Which role family does the job described in `posting` belong to?',
      how_to_judge: 'Judge from `posting.title` and the duties in `posting.description`. ' +
        'Ignore which department or team the job sits in: a developer advocate in a marketing department ' +
        'is still developer relations.',
    },
    criteria: families,
  },
  stack_fit: {
    type: 'score',
    instructions: 'How much of the technology that the job in `posting` works with is in the candidate\'s skills in `profile.summary`?',
    criteria: [
      'None of the languages, frameworks or platforms the job uses are in the candidate\'s skills',
      'Only minor tools overlap; the job\'s main languages and frameworks are different',
      'Some core technologies overlap, but a main language or framework is different',
      'Most of the job\'s core languages and frameworks are in the candidate\'s skills',
      'The job\'s technology is essentially the candidate\'s skills',
    ],
  },
  names_stack: {
    type: 'noul',
    instructions: 'Does `posting.description` name specific programming languages, frameworks or technical platforms used in this job?',
  },
  seniority: {
    type: 'choice',
    instructions: 'What seniority level is the job in `posting`, based on `posting.title` and `posting.description`?',
    criteria: {
      intern_junior: 'Intern, new graduate, junior or associate level',
      mid: 'Mid-level individual contributor, with no senior, lead or staff title',
      senior: 'Senior individual contributor, such as Senior Engineer or Senior Developer Advocate',
      lead: 'Lead individual contributor or team lead, such as Lead Engineer, Tech Lead or a title ending in Lead',
      staff_plus: 'Staff, principal or distinguished individual contributor',
      manager: 'Manages people or a function: engineering manager, head of a team, director or VP',
      founding: 'Founding or first hire on a team, such as Founding Engineer',
      not_stated: 'The title and description don\'t indicate a level',
    },
  },
  domain_fit: {
    type: 'score',
    instructions: 'How closely do the product area and the users of the job in `posting` match the domains in `profile.summary`?',
    criteria: [
      'Unrelated to any domain in the candidate\'s profile',
      'Loosely related: a different product area, with some transferable context',
      'Adjacent: a closely related product area or the same kind of users',
      'The same domain the profile names, such as the same kind of product and users',
    ],
  },
};

// Only for postings with no structured pay: Jev picks the base salary among the dollar
// amounts a regex found in the description, or none. Code compares it with the floor.
function payQuestion(mentions) {
  const criteria = {};
  for (const m of mentions) criteria[m.span] = null;
  criteria.none = 'None of these is the job\'s base salary: they are funding, revenue, customer size, benefits, ' +
    'equity, bonus, commission or other amounts';
  return {
    type: 'choice',
    instructions: 'Which of these amounts is the base salary or base salary range for the job in `posting`, ' +
      'in US dollars per year? `posting.pay_mentions` shows where each amount appears.',
    criteria,
  };
}

const out = [];
for (const { json: lead } of $input.all()) {
  if (!lead.lead_key || lead.closed_at) continue;
  if (daysSinceFirstSeen(lead) > windowDays) continue;
  const p = postings.get(lead.lead_key);
  if (!p) continue; // not in today's fetch: its board failed or the posting is gone

  const location = [p.location_text, p.workplace_type, p.secondary_locations && 'also: ' + p.secondary_locations]
    .filter(Boolean).join(' · ');
  const posting = {
    title: p.title,
    company: p.company,
    location: location || 'Not stated',
    pay: p.pay_text || 'Not stated',
    description: p.description || '',
  };
  const questions = { ...QUESTIONS };
  const mentions = p.pay_min == null && p.pay_max == null ? p.salary_mentions || [] : [];
  if (mentions.length) {
    posting.pay_mentions = mentions.map((m) => m.context);
    questions.base_salary = payQuestion(mentions);
  }
  const body = {
    model: cfg.jevModel,
    state: {
      profile: { summary: cfg.profileSummary, role_families: (cfg.roleFamilies || []).map((f) => f.name) },
      posting,
    },
    questions,
  };
  const fingerprint = fingerprintOf(JSON.stringify(body));
  if (lead.scoring_state === 'scored' && lead.scoring_fingerprint === fingerprint) continue;
  out.push({ json: { id: lead.id, lead_key: lead.lead_key, scoring_fingerprint: fingerprint, jev_body: body } });
}

// A fixed order, so test fixtures can line up with the requests.
out.sort((a, b) => (a.json.lead_key < b.json.lead_key ? -1 : 1));
return out;

// Turns each Jev response into stored judgments, each normalized to 0-1:
//   sub_role_family: the probability that the job is in one of the configured families
//   sub_stack:       stack overlap; when the posting names no stack, it counts as 0.5
//   sub_domain:      domain overlap
// The seniority answer is stored and turned into a sub-score in Score and select, so
// changing targetSeniority needs no new Jev calls.
// Ask Jev tries each request once. The ones that failed were tried again by Ask Jev
// again, and those responses replace the failed ones here. A response that still has
// no valid answers leaves the lead unscored: it isn't sent, the header counts it, and
// it is judged again on the next scan.
const requests = $('Build Jev requests').all();
const responses = $('Ask Jev').all().map((i) => i.json);
if (requests.length !== responses.length) {
  throw new Error(`Jev returned ${responses.length} responses for ${requests.length} requests`);
}
if ($('Ask Jev again').isExecuted) {
  const retried = $('Jev requests to retry').all();
  const again = $('Ask Jev again').all();
  if (retried.length !== again.length) {
    throw new Error(`Jev returned ${again.length} responses for ${retried.length} retried requests`);
  }
  const byKey = new Map(retried.map((r, i) => [r.json.lead_key, again[i].json]));
  requests.forEach((r, i) => {
    if (byKey.has(r.json.lead_key)) responses[i] = byKey.get(r.json.lead_key);
  });
}
const NONE = 'None of these';
const round = (n, d = 3) => Math.round(n * 10 ** d) / 10 ** d;
const probs = (p) => Object.fromEntries(Object.entries(p || {}).map(([k, v]) => [k, round(v)]));
const top = (q) => q.criteria.length - 1;

// "$150,000 - $190,000" or "$160K–$200K" -> [150000, 190000]
function amounts(span) {
  return (span.match(/\d[\d,]*(?:\.\d+)?\s?[kK]?/g) || []).map((a) => {
    const n = parseFloat(a.replace(/,/g, ''));
    return /k$/i.test(a.trim()) ? n * 1000 : n;
  });
}

return responses.map((json, i) => {
  const item = { json };
  const req = requests[i].json;
  const q = req.jev_body.questions;
  const a = (item.json && item.json.answers) || {};
  const valid = ['role_family', 'stack_fit', 'names_stack', 'seniority', 'domain_fit']
    .concat(q.base_salary ? ['base_salary'] : [])
    .every((id) => a[id] && a[id].type === q[id].type);
  if (!valid) return { json: { id: req.id, scoring_state: 'unscored' } };

  const namesStack = a.names_stack.noul;
  const stack = namesStack * (a.stack_fit.score / top(q.stack_fit)) + (1 - namesStack) * 0.5;
  let pay = { text: null, min: null, max: null };
  if (a.base_salary && a.base_salary.choice !== 'none') {
    const values = amounts(a.base_salary.choice);
    pay = { text: a.base_salary.choice, min: Math.min(...values), max: Math.max(...values) };
  }
  const answers = {
    role_family: { choice: a.role_family.choice, confidence: round(a.role_family.confidence), p: probs(a.role_family.probabilities) },
    stack_fit: { score: round(a.stack_fit.score), confidence: round(a.stack_fit.confidence) },
    names_stack: { noul: round(namesStack) },
    seniority: { choice: a.seniority.choice, confidence: round(a.seniority.confidence), p: probs(a.seniority.probabilities) },
    domain_fit: { score: round(a.domain_fit.score), confidence: round(a.domain_fit.confidence) },
  };
  if (a.base_salary) answers.base_salary = { choice: a.base_salary.choice, confidence: round(a.base_salary.confidence) };

  return {
    json: {
      id: req.id,
      scoring_state: 'scored',
      scoring_fingerprint: req.scoring_fingerprint,
      scored_at: new Date().toISOString(),
      jev_model: item.json.model || req.jev_body.model,
      jev_answers: JSON.stringify(answers),
      role_family: a.role_family.choice,
      seniority_level: a.seniority.choice,
      sub_role_family: round(1 - ((a.role_family.probabilities || {})[NONE] || 0)),
      sub_stack: round(stack),
      sub_domain: round(a.domain_fit.score / top(q.domain_fit)),
      pay_extracted_text: pay.text,
      pay_extracted_min: pay.min,
      pay_extracted_max: pay.max,
    },
  };
});

// Fit score for every candidate lead, recomputed on every scan from the stored Jev
// judgments and the current config, so a weight change re-ranks leads with no new
// Jev calls. Code adds the sub-scores Jev doesn't judge:
//   seniority: 1 for a level in targetSeniority, 0.5 when the posting states no level,
//              0.2 for any other level (weighted by Jev's probability for each level)
//   location:  1 for US-remote or a configured metro, 0.5 for "Location unclear"
//   freshness: by the posting's age (the earlier of published and first seen): 1 for a
//              posting from today, falling to 0 at freshnessWindowDays and staying 0
//   referral:  1 when the lead's company is in the referrals table (the Referral
//              button), else 0
// Each sub-score (0-1) times its weight, scaled so all weights add up to 100, is its
// points, and the fit score is the sum of the points. A lead can be sent when it is
// not closed, scored, passed the filters, New, unsent, first seen no more than
// freshnessWindowDays ago, in one of the role families (Jev's top answer isn't
// "None of these"), and at or above minFitScore. selection_reason records the first of
// these that held a lead back ("closed" for a posting gone from its board), or "eligible".
const cfg = $('Job Scout config').first().json;
const DAY = 24 * 60 * 60 * 1000;
const windowDays = Number(cfg.freshnessWindowDays) || 30;
const minFit = Number(cfg.minFitScore) || 0;
const payFloor = Number(cfg.payFloor) || 0;
const target = new Set((cfg.targetSeniority || []).map((s) => String(s).toLowerCase()));
const LOCATION = { us_remote: 1, metro: 1, unclear: 0.5 };
const DIMENSIONS = ['roleFamily', 'stack', 'seniority', 'location', 'domain', 'freshness', 'referral'];
const weights = cfg.weights || {};
const totalWeight = DIMENSIONS.reduce((s, d) => s + (Number(weights[d]) || 0), 0) || 1;
const round = (n, d = 3) => Math.round(n * 10 ** d) / 10 ** d;
// A company's key: its name in lower case with only letters and digits, so "PostHog"
// and "posthog" match.
const companyKey = (name) => String(name || '').toLowerCase().replace(/[^\p{L}\p{N}]/gu, '');
const referred = new Set($('Get referrals').all().map((i) => i.json.company_key).filter(Boolean));

// New judgments from this scan, by row id.
const judged = new Map();
if ($('Read Jev answers').isExecuted) {
  for (const { json } of $('Read Jev answers').all()) judged.set(json.id, json);
}

const NONE = 'None of these';
const daysSince = (d) => (Date.now() - new Date(d).getTime()) / DAY;
// The posting's age, for the freshness sub-score.
function postingAge(lead) {
  const ages = [lead.published_at, lead.first_seen_at].filter(Boolean).map(daysSince).filter((a) => !isNaN(a));
  return ages.length ? Math.max(...ages) : 0;
}
// Days since Job Scout first saw the lead, for the freshness window.
const sinceFirstSeen = (lead) => (lead.first_seen_at ? daysSince(lead.first_seen_at) : 0);

function seniorityScore(lead) {
  let p = {};
  try {
    p = JSON.parse(lead.jev_answers || '{}').seniority.p || {};
  } catch (e) {
    p = {};
  }
  const value = (level) => (target.has(level) ? 1 : level === 'not_stated' ? 0.5 : 0.2);
  const entries = Object.entries(p);
  if (!entries.length) return value(lead.seniority_level);
  return entries.reduce((s, [level, prob]) => s + prob * value(level), 0);
}

return $('Get candidate leads').all().filter((i) => i.json.lead_key).map(({ json: row }) => {
  const lead = { ...row, ...(judged.get(row.id) || {}) };
  const age = postingAge(lead);
  const sub = {
    roleFamily: lead.sub_role_family,
    stack: lead.sub_stack,
    seniority: seniorityScore(lead),
    location: LOCATION[lead.location_basis] ?? 0,
    domain: lead.sub_domain,
    freshness: Math.max(0, 1 - age / windowDays),
    referral: referred.has(companyKey(lead.company)) ? 1 : 0,
  };

  // Pay stated only in the description: Jev picked the span, code checks the floor.
  let filterResult = lead.filter_result;
  if (lead.pay_min == null && lead.pay_max == null && typeof lead.pay_extracted_max === 'number' &&
      lead.pay_extracted_max < payFloor) {
    filterResult = 'pay_floor';
  }

  const scored = lead.scoring_state === 'scored';
  let points = null;
  let fit = null;
  if (scored) {
    points = {};
    for (const d of DIMENSIONS) points[d] = Math.round((100 * (Number(weights[d]) || 0) * (sub[d] || 0)) / totalWeight);
