  if (lead.closed_at) reason = 'closed';
  else if (!scored) reason = 'unscored';
  else if (filterResult !== 'passed') reason = filterResult;
  else if (lead.role_family === NONE) reason = 'no_role_family';
  else if (sinceFirstSeen(lead) > windowDays) reason = 'window_passed';
