// newer posting. Leads that miss the cap stay New and compete again on the next scan.
// Each picked lead carries its posting description for the fit line.
const cfg = $('Job Scout config').first().json;
const cap = Math.max(0, Number(cfg.dailyCap) || 0);
const descriptions = new Map($('Normalize postings').all().map((i) => [i.json.lead_key, i.json.description]));
const time = (d) => (d ? new Date(d).getTime() : 0);

return $('Score and select').all()
  .map((i) => i.json)
  .filter((lead) => lead.eligible)
  .sort((a, b) => b.fit_score - a.fit_score || time(b.published_at) - time(a.published_at) ||
    (a.lead_key < b.lead_key ? -1 : 1))
  .slice(0, cap)
  .map((lead) => ({ json: { ...lead, description: descriptions.get(lead.lead_key) || '' } }));

