const DIMENSIONS = ['roleFamily', 'stack', 'seniority', 'location', 'domain', 'freshness', 'referral'];
const totalWeight = DIMENSIONS.reduce((s, d) => s + (Number(weights[d]) || 0), 0) || 1;
// Points for a referral sub-score, rounded as Score and select rounds them.
const referralPoints = (sub) => Math.round((100 * (Number(weights.referral) || 0) * (Number(sub) || 0)) / totalWeight);
const minFit = Number(cfg.minFitScore) || 0;
const company = $('Check Referral link').first().json.company_key;
return $input.all().map((i) => i.json)
  .filter((lead) => lead.id && companyKey(lead.company) === company && Number(lead.sub_referral) !== 1)
  .map((lead) => {
    const scored = typeof lead.fit_score === 'number';
    const fit = scored ? lead.fit_score - referralPoints(lead.sub_referral) + referralPoints(1) : lead.fit_score;
    let reason = lead.selection_reason;
    if (scored && (reason === 'below_min_fit' || reason === 'eligible')) {
      reason = fit >= minFit ? 'eligible' : 'below_min_fit';
    }
    return { json: { id: lead.id, lead_key: lead.lead_key, sub_referral: 1, fit_score: fit, selection_reason: reason } };
  });

// The page after a referral is saved.
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');
const cfg = $('Job Scout config').first().json;
const weights = cfg.weights || {};
const DIMENSIONS = ['roleFamily', 'stack', 'seniority', 'location', 'domain', 'freshness', 'referral'];
const totalWeight = DIMENSIONS.reduce((s, d) => s + (Number(weights[d]) || 0), 0) || 1;
// Points for a referral sub-score, rounded as Score and select rounds them.
const referralPoints = (sub) => Math.round((100 * (Number(weights.referral) || 0) * (Number(sub) || 0)) / totalWeight);
const r = $('Check Referral link').first().json;
const rescored = $('Rescore company leads').all().filter((i) => i.json.lead_key).length;
const company = '<b>' + esc(r.company) + '</b>';
const lines = [company,
  'Every current and future lead from ' + esc(r.company) + ' gets the referral points (+' + referralPoints(1) +
  ') and shows "Referral available".'];
if (rescored) lines.push(rescored + ' unsent ' + (rescored === 1 ? 'lead was' : 'leads were') + ' rescored.');
return [{ json: { http_status: 200, heading: 'Referral saved', lines } }];

// Pass: the job seeker isn't pursuing the lead. Nothing changes unless the link's
// signature matches and the form names one of the ten pass reasons. A New or Picked
// lead becomes Passed with today's date, so it is never sent again, and its reason and
// note go in the passes table (one row per lead). Passing a Passed lead again replaces
// the reason and note in that row and keeps the first date. An Applied lead isn't changed.
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');
// The page's heading and lines; lines are HTML, so posting text is escaped.
const page = (http_status, heading, lines, extra = {}) => [{ json: { http_status, heading, lines, ...extra } }];
// The ten pass reasons: the label the form shows, and the code that is saved. They must
// match the Reason options on Pass form.
const REASONS = {
  'Comp below range': 'comp_below_range',
  'Wrong seniority': 'seniority_mismatch',
  'Not my role family': 'role_family_off',
  'Remote claim is soft': 'location_not_real',
  'Company stage off': 'company_stage_off',
  'Stack mismatch': 'tech_stack_off',
  'Already applied': 'already_applied',
  'Not interested': 'no_interest',
  'Listing looks wrong': 'listing_looks_wrong',
  'Stale repost': 'stale_repost',
};
const LABELS = Object.fromEntries(Object.entries(REASONS).map(([label, code]) => [code, label]));

// ---- Signed action links (the same block is in Build lead messages, Check Applied link,
// Check Referral link and Check Pass form). A link's signature is HMAC-SHA256 of "<action>:<lead key>"
// with the signing secret, as hex, cut to 32 characters (128 bits). HMAC-SHA256 is
// written out here because the Code node can't load Node's crypto module unless the
// instance allows it (NODE_FUNCTION_ALLOW_BUILTIN), and the Crypto node's HMAC reads
// its secret from a credential.
const K = [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];
const rotr = (x, n) => (x >>> n) | (x << (32 - n));
const utf8 = (s) => Array.from(new TextEncoder().encode(String(s)));
function sha256(input) {
  const bytes = input.slice();
  const bits = input.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  for (let i = 7; i >= 0; i--) bytes.push(i >= 4 ? 0 : (bits >>> (8 * i)) & 0xff);
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const w = new Array(64);
  for (let off = 0; off < bytes.length; off += 64) {
    for (let t = 0; t < 16; t++) {
      const j = off + 4 * t;
      w[t] = ((bytes[j] << 24) | (bytes[j + 1] << 16) | (bytes[j + 2] << 8) | bytes[j + 3]) >>> 0;
    }
    for (let t = 16; t < 64; t++) {
      const s0 = rotr(w[t - 15], 7) ^ rotr(w[t - 15], 18) ^ (w[t - 15] >>> 3);
      const s1 = rotr(w[t - 2], 17) ^ rotr(w[t - 2], 19) ^ (w[t - 2] >>> 10);
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let t = 0; t < 64; t++) {
      const t1 = (h + (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) + ((e & f) ^ (~e & g)) + K[t] + w[t]) >>> 0;
      const t2 = ((rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    [a, b, c, d, e, f, g, h].forEach((v, i) => { H[i] = (H[i] + v) >>> 0; });
  }
  return H.flatMap((x) => [x >>> 24, (x >>> 16) & 0xff, (x >>> 8) & 0xff, x & 0xff]);
}
function hmacSha256Hex(key, message) {
  let k = utf8(key);
  if (k.length > 64) k = sha256(k);
  while (k.length < 64) k.push(0);
  const inner = sha256(k.map((x) => x ^ 0x36).concat(utf8(message)));
  return sha256(k.map((x) => x ^ 0x5c).concat(inner)).map((x) => x.toString(16).padStart(2, '0')).join('');
}
const sign = (action, leadKey, secret) => hmacSha256Hex(secret, action + ':' + leadKey).slice(0, 32);
// Compares every character, so the time taken doesn't show how much of a guess was right.
function sameSignature(given, expected) {
  const a = String(given || '');
  let diff = a.length ^ expected.length;
  for (let i = 0; i < expected.length; i++) diff |= (a.charCodeAt(i) || 0) ^ expected.charCodeAt(i);
  return diff === 0;
}
// ---- end of signed action links

const form = $('Pass form').first().json;
const key = String(form.lead || '');
const secret = $('Signing secret').first().json.secret;
if (!key || !secret || !sameSignature(form.sig, sign('pass', key, secret))) {
  return page(403, 'Invalid link', ['This link is not valid, so nothing was changed.']);
}
const lead = $input.first().json;
if (!lead.id || lead.lead_key !== key) return page(404, 'Lead not found', ['Nothing was changed.']);
const what = '<b>' + esc(lead.title) + '</b> at ' + esc(lead.company);
// The form requires a reason; this catches a submission that skipped the form.
const choice = String(form['Reason'] || '').trim();
const reason_code = REASONS[choice] || '';
if (!reason_code) {
  return page(400, 'Pick a reason', [what, 'A pass needs one of the ten reasons. Nothing was changed.']);
}
const note = String(form['Anything else? (optional)'] || '').trim().slice(0, 2000);
const label = esc(LABELS[reason_code]);
if (lead.status === 'passed') {
  const passed_at = lead.passed_at || $now.toISO();
  const on = lead.passed_at ? 'Passed on ' + String(lead.passed_at).slice(0, 10) + '.' : '';
  return page(200, 'Already passed', [what, on, 'Reason updated: ' + label + '.'],
    { save: true, mark: false, row_id: lead.id, lead_key: key, reason_code, note, passed_at });
}
if (lead.status !== 'new' && lead.status !== 'picked') {
  return page(409, 'Not changed', [what, 'Pass works for New or Picked leads. This lead is ' +
    esc(lead.status || 'not set') + '.']);
}
return page(200, 'Passed', [what, 'Reason logged: ' + label + '.', "Job Scout won't send this lead again."],
  { save: true, mark: true, row_id: lead.id, lead_key: key, reason_code, note, passed_at: $now.toISO() });
